mapper.select:
SELECT 
FROM ssm_governance_exempt

    AND object_scope = #{objectScope}

ORDER BY id DESC
LIMIT #{startNum}, #{pageSize}

mapper.insert:
INSERT INTO ssm_governance_exempt (
    object_scope, module_name, ctg_id, ctg_name, reason, is_active, created_by, created_time, updated_time
) VALUES (
    #{objectScope}, #{moduleName}, #{ctgId}, #{ctgName}, #{reason}, #{isActive}, #{createdBy}, now(), now()
)
